/** Invert only the native allowlisted appearance belonging to this actor.
 * The raw catalog row and its display IDs (including iSelLmtParam) stay intact.
 * Buff translation is owned by the caster, not by the recipient (skin_effects.py).
 */
export function nativeTemplateId(kind, id, actor, catalog) {
  id = Number(id);
  const tankId = actor?.tankId ?? actor?.ownerTankIdAtSnapshot;
  const externalId = actor?.externalId ?? actor?.ownerExternalIdAtSnapshot;
  const spec = catalog?.dependencyManifests?.tanks?.[String(tankId)]
    ?.skins?.[String(externalId)]?.presentationRemap;
  if (!spec || Number(spec.tank) !== Number(tankId)) return id;
  if ((Number(actor?.objectId) >>> 26) !== 0 && !Object.entries(spec.npc ?? {})
      .some(([base, display]) => [Number(base), Number(display)].includes(Number(actor?.templateId)))) return id;
  const matches = Object.entries(spec[kind] ?? {}).filter(([, display]) => Number(display) === id);
  return matches.length === 1 ? Number(matches[0][0]) : matches.length ? null : id;
}

export function isNativeCopyTarget(actor) {
  // KakashiBorrowing.cast_borrowed: regular current native tank, excluding
  // Kakashi itself and all npc_template actors. No numbered-ID range guessing.
  return !!actor && (actor.objectId >>> 26) === 0 && nativeTanks.has(Number(actor.tankId))
    && Number(actor.tankId) !== 10000055 && !actor.templateId;
}

export function canCastOnSelf(skill) {
  const type = Number(skill?.iSType ?? 0), limit = Number(skill?.iSelectLimit) || 0;
  return type === 0 || type === 3 && !!(limit & SELECT.TEAMMATE) && !(limit & SELECT.NOT_SELF);
}

